/* Fichier généré par build.mjs — ne pas modifier : modifier src/ puis relancer le build */
var ASSETS_B64 = {"logo-augeexco.png":"","logo-numria.png":"","squares-augeexco.png":"","stars-numria.png":""};

/*
 * CONFIGURATION DES SIGNATURES
 * ----------------------------
 * C'est le seul fichier à modifier pour ajouter un collaborateur ou changer
 * une adresse, un téléphone, une fonction. Ensuite : node build.mjs <adresse-https>
 *
 * FIRMS    : les deux sociétés (adresse, site, couleurs, logos).
 * PROFILES : une entrée par adresse d'expédition. Quand l'adresse "De" du
 *            message correspond à une entrée, la signature de la société
 *            correspondante est insérée avec les infos de cette personne.
 */

var FIRMS = {
  augeexco: {
    layout: 'logo-right',          // logo à droite du texte
    website: 'www.augeexco.fr',
    websiteUrl: 'http://www.augeexco.fr/',
    addressLines: ['90 avenue Claude Farrère', '83000 Toulon'],
    reception: '04 94 46 50 46',   // ligne "Accueil"
    colors: { name: '#0D3449', text: '#1D71B8', link: '#467886', reception: '#0D3449' },
    logo:   { file: 'logo-augeexco.png',    width: 219, height: 268 },
    accent: { file: 'squares-augeexco.png', width: 60,  height: 17 }
  },
  numria: {
    layout: 'logo-left',           // logo à gauche du texte
    website: null,
    websiteUrl: null,
    addressLines: ['61 Impasse Joseph Farnous', '83160 La Valette du Var'],
    reception: '04 94 27 25 25',
    colors: { name: '#0D3449', text: '#006600', link: '#467886', address: '#242424', reception: '#0D3449' },
    logo:   { file: 'logo-numria.png',  width: 174, height: 216 },
    accent: { file: 'stars-numria.png', width: 72,  height: 12 }
  }
};

var PROFILES = [
  {
    address: 'geoffrey.venturini@augeexco.fr',
    firm: 'augeexco',
    name: 'Geoffrey VENTURINI',
    titles: ['Expert-comptable', 'Commissaire aux comptes']
  },
  {
    address: 'geoffrey.venturini@num-ria.fr',
    firm: 'numria',
    name: 'Geoffrey VENTURINI',
    titles: ['Expert-Comptable'],
    phone: '04 94 27 25 25'
  }
  /* Exemple pour un collaborateur (à décommenter et adapter) :
  ,{
    address: 'prenom.nom@num-ria.fr',
    firm: 'numria',
    name: 'Prénom NOM',
    titles: ['Collaborateur social'],
    phone: '04 94 27 25 25'
  }
  */
];

/*
 * Construction du HTML des signatures (reproduit la mise en page de vos
 * signatures Outlook actuelles). Les images sont référencées par "cid:" :
 * elles sont jointes au message en "image incorporée" par commands.js.
 */

function sigEsc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function sigCid(file) {
  return 'sig-' + file;
}

function sigP(content, color, extra) {
  return '<p style="margin:0cm;font-family:Arial,sans-serif;font-size:12pt;line-height:105%;' +
    (color ? 'color:' + color + ';' : '') + (extra || '') + '">' + content + '</p>';
}

function sigBlank() {
  return sigP('&nbsp;');
}

function sigImg(asset) {
  return '<img src="cid:' + sigCid(asset.file) + '" width="' + asset.width + '" height="' + asset.height +
    '" alt="" style="width:' + asset.width + 'px;height:' + asset.height + 'px;border:0;">';
}

function sigLink(href, label, color) {
  return '<a href="' + sigEsc(href) + '" style="color:' + color + ';"><u>' + sigEsc(label) + '</u></a>';
}

function buildSignatureHtml(profile, firm) {
  var c = firm.colors;
  var lines = [];

  lines.push(sigP('<b>' + sigEsc(profile.name) + '</b>', c.name));
  profile.titles.forEach(function (t) { lines.push(sigP(sigEsc(t), c.text)); });
  lines.push(sigP(sigImg(firm.accent)));
  if (profile.firm === 'numria') { lines.push(sigBlank()); }

  if (profile.phone) { lines.push(sigP(sigEsc(profile.phone), c.name)); }
  lines.push(sigP(sigLink('mailto:' + profile.address, profile.address, c.link)));
  if (profile.firm === 'numria') { lines.push(sigBlank()); }

  firm.addressLines.forEach(function (l) { lines.push(sigP(sigEsc(l), c.address || c.text)); });
  if (profile.firm === 'numria') { lines.push(sigBlank()); }

  lines.push(sigP('Accueil&nbsp;: ' + sigEsc(firm.reception), c.reception));
  if (firm.website) { lines.push(sigP(sigLink(firm.websiteUrl, firm.website, c.link))); }

  var textCell = '<td style="vertical-align:top;padding:0cm 5.4pt;">' + lines.join('') + '</td>';
  var logoCell = '<td style="vertical-align:top;padding:0cm 5.4pt;">' + sigImg(firm.logo) + '</td>';

  var cells = firm.layout === 'logo-left' ? logoCell + textCell : textCell + logoCell;
  return '<table cellspacing="0" cellpadding="0" border="0" ' +
    'style="border-collapse:collapse;border-spacing:0;background-color:#ffffff;"><tbody><tr>' +
    cells + '</tr></tbody></table>';
}

/* Retourne {html, assets:[{file,base64}]} pour une adresse d'expédition, ou null. */
function findSignatureFor(address) {
  if (!address) { return null; }
  var a = String(address).trim().toLowerCase();
  for (var i = 0; i < PROFILES.length; i++) {
    if (PROFILES[i].address.toLowerCase() === a) {
      var p = PROFILES[i];
      var firm = FIRMS[p.firm];
      return {
        html: buildSignatureHtml(p, firm),
        assets: [firm.logo, firm.accent]
      };
    }
  }
  return null;
}

/*
 * Complément Outlook : signature automatique selon l'adresse d'expédition.
 *
 * - À la création d'un message / d'une réponse (OnNewMessageCompose) et à chaque
 *   changement de l'adresse "De" (OnMessageFromChanged), on lit l'adresse
 *   d'expédition, on retire les images de l'ancienne signature, puis on pose la
 *   signature de la bonne société.
 * - Adresse inconnue (boîtes "contact", etc.) : on ne touche à rien.
 *
 * Ce fichier est assemblé par build.mjs avec config.js, signature.js et les logos
 * (ASSETS_B64 est généré). Ne pas utiliser import/export ici : Outlook classique
 * ne les supporte pas dans les gestionnaires d'événements.
 */

var SIG_PREFIX = 'sig-';

function callAsync(fn, options) {
  return new Promise(function (resolve, reject) {
    var cb = function (result) {
      if (result.status === Office.AsyncResultStatus.Succeeded) { resolve(result.value); }
      else { reject(result.error); }
    };
    if (options === undefined) { fn(cb); } else { fn(options, cb); }
  });
}

function removeOldSignatureImages(item) {
  return callAsync(item.getAttachmentsAsync.bind(item)).then(function (attachments) {
    var old = (attachments || []).filter(function (a) {
      return a.name && a.name.indexOf(SIG_PREFIX) === 0;
    });
    return Promise.all(old.map(function (a) {
      return callAsync(item.removeAttachmentAsync.bind(item, a.id)).catch(function () { /* déjà retiré */ });
    }));
  });
}

function addSignatureImages(item, assets) {
  return assets.reduce(function (chain, asset) {
    return chain.then(function () {
      return callAsync(
        item.addFileAttachmentFromBase64Async.bind(item, ASSETS_B64[asset.file], sigCid(asset.file), { isInline: true })
      );
    });
  }, Promise.resolve());
}

function setSignatureHtml(item, html) {
  return callAsync(item.body.setSignatureAsync.bind(item.body, html, { coercionType: Office.CoercionType.Html }));
}

var DIAG_ON = true; // diagnostic temporaire : ligne rouge en bas de la signature
function diagHtml(txt) {
  return DIAG_ON ? '<p style="color:#c00000;font:9px Arial">diag : ' + String(txt).replace(/[<>&]/g, '') + '</p>' : '';
}

var step = 'début';
function applySignatureForCurrentFrom(evName) {
  var item = Office.context.mailbox.item;
  step = 'lecture de De';
  return callAsync(item.from.getAsync.bind(item.from)).then(function (from) {
    var addr = from && from.emailAddress;
    var sig = findSignatureFor(addr);
    var info = evName + ' / De=' + addr + ' / ' + (sig ? 'signature trouvee' : 'AUCUNE signature');
    if (!sig) { step = 'pose diag'; return DIAG_ON ? setSignatureHtml(item, diagHtml(info)) : null; }
    step = 'retrait anciennes images';
    return removeOldSignatureImages(item)
      .then(function () { step = 'ajout images'; return addSignatureImages(item, sig.assets); })
      .then(function () { step = 'pose signature'; return setSignatureHtml(item, sig.html + diagHtml(info)); });
  });
}

function reportError(evName, err) {
  var msg = evName + ' ERREUR a l etape [' + step + '] : ' + (err && (err.message || err.code) ? (err.message || '') + ' ' + (err.code || '') : JSON.stringify(err));
  console.log('Signature : ' + msg);
  try { return setSignatureHtml(Office.context.mailbox.item, diagHtml(msg)).catch(function () {}); } catch (e) { return Promise.resolve(); }
}

function runHandler(event, evName) {
  var done = false;
  var finish = function () { if (!done) { done = true; event.completed(); } };
  try {
    applySignatureForCurrentFrom(evName).then(finish, function (err) {
      reportError(evName, err).then(finish, finish);
    });
  } catch (e) {
    reportError(evName, e).then(finish, finish);
  }
}

function onNewMessageComposeHandler(event) { runHandler(event, 'Création'); }
function onMessageFromChangedHandler(event) { runHandler(event, 'Changement De'); }

// Nécessaire pour qu'Outlook sur le web initialise la bibliothèque avant l'association des gestionnaires
Office.onReady();
Office.actions.associate('onNewMessageComposeHandler', onNewMessageComposeHandler);
Office.actions.associate('onMessageFromChangedHandler', onMessageFromChangedHandler);
